mount -t tracefs nodev /sys/kernel/tracing; cat /sys/kernel/tracing/trace_clock /sys/kernel/tracing/current_tracer /sys/kernel/tracing/available_tracers; ls /sys/kernel/tracing/instances; for e in sched/sched_waking sched/sched_wakeup sched/sched_switch irq/irq_handler_entry irq/irq_handler_exit irq/softirq_entry irq/softirq_exit; do ls /sys/kernel/tracing/events/$e/enable; done; dmesg | grep -i -E "pmu|perf|panic|Oops:|BUG:|Call trace:"; cat /sys/devices/system/cpu/cpufreq/policy0/scaling_governor /sys/devices/system/cpu/cpufreq/policy0/scaling_cur_freq /proc/sys/kernel/sched_rt_period_us /proc/sys/kernel/sched_rt_runtime_us
